using System;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[Serializable]
public class OverCorruptionAction
{
	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	private int actionAmount;

	public BattleAction BattleAction => battleAction;

	public int ActionAmount => actionAmount;

	public OverCorruptionAction(BattleAction battleAction, int actionAmount)
	{
		if (battleAction != null)
		{
			this.battleAction = battleAction;
		}
		this.actionAmount = actionAmount;
	}

	public string ValueText(int value)
	{
		if (value == EffectsValues.NO_VALUE)
		{
			return " ";
		}
		return value.ToString();
	}
}
